// M2 · Read the "Event closed" form. Transcript upload is optional: without it, the recording file is transcribed by Deepgram.

const f = $input.first();
const binKey = Object.keys(f.binary || {})[0];
const uploaded = binKey ? (await this.helpers.getBinaryDataBuffer(0, binKey)).toString('utf8').trim() : '';
const recordingFile = (f.json['Recording file URL'] || '').trim();
if (!uploaded && !recordingFile) throw new Error('Give a recording file URL (mp3/mp4/m4a) or upload a transcript');
const event = (f.json['Event name'] || '').trim();
const slug = event.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 40);

return [{ json: {
  event, slug, runId: 'm2-' + new Date().toISOString().replace(/[-:T]/g, '').slice(0, 12),
  uploaded_transcript: uploaded, recording_file_url: recordingFile,
  recording_url: (f.json['Watch link for emails'] || recordingFile).trim(),
  cta_url: (f.json['CTA link'] || '').trim(),
  from_name: (f.json['From name'] || 'Webinar Team').trim(),
  reply_to: (f.json['Reply-to email'] || '').trim(),
  mode: String(f.json['Mode'] || '').toLowerCase().startsWith('send') ? 'send' : 'draft',
  utm_campaign: `${slug}-postevent`,
} }];

// M2 · Decide how to get the transcript and build the Deepgram request.
// Keyterm prompting with the event + speaker names fixes brand/name spellings (e.g. "Darwinbox", "Jayant").

const inp = $('Read inputs').first().json;
const contacts = $input.all().flatMap(i => i.json.results || []).map(r => ({ id: r.id, ...r.properties }));
const speakers = contacts.filter(c => c.event_attendance_status === 'speaker');
const terms = [...new Set([
  ...speakers.flatMap(s => [s.firstname, s.lastname, s.company]),
  ...inp.event.split(/[^A-Za-z0-9-]+/).filter(w => /^[A-Z]/.test(w) && w.length > 3),
].filter(Boolean))].slice(0, 20);
const needDeepgram = !inp.uploaded_transcript;
// (n8n's Code sandbox has no URL/URLSearchParams, so build the query string by hand)
const params = ['model=nova-3', 'diarize=true', 'paragraphs=true', 'smart_format=true', 'punctuate=true', 'language=en',
  ...terms.map(t => 'keyterm=' + encodeURIComponent(t))].join('&');

return [{ json: {
  contacts, need_deepgram: needDeepgram, keyterms: terms,
  // Without a recording to transcribe, call a harmless Deepgram endpoint instead (keeps the flow branch-free).
  dg_method: needDeepgram ? 'POST' : 'GET',
  dg_url: needDeepgram ? `https://api.deepgram.com/v1/listen?${params}` : 'https://api.deepgram.com/v1/projects',
  dg_body: needDeepgram ? { url: inp.recording_file_url } : {},
} }];

// M2 · Turn Deepgram's paragraphs into "[mm:ss] Speaker N: text" lines (or pass the uploaded transcript through).

const inp = $('Read inputs').first().json;
const prep = $('Prepare transcription').first().json;
let transcript = inp.uploaded_transcript, source = 'uploaded transcript', duration = null;
if (prep.need_deepgram) {
  const alt = $json.results?.channels?.[0]?.alternatives?.[0];
  if (!alt) throw new Error('Deepgram returned no transcript: ' + JSON.stringify($json).slice(0, 300));
  const mmss = s => `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(Math.floor(s % 60)).padStart(2, '0')}`;
  transcript = (alt.paragraphs?.paragraphs || []).map(p => `[${mmss(p.start)}] Speaker ${p.speaker}: ${p.sentences.map(s => s.text).join(' ')}`).join('\n');
  source = `Deepgram nova-3 (diarized, keyterms: ${prep.keyterms.join(', ')})`;
  duration = Math.round($json.metadata?.duration || 0);
}
return [{ json: { transcript, source, duration_s: duration, chars: transcript.length } }];

// M2 · Build the DeepSeek request that pulls takeaways + verbatim quotes out of the transcript.

const inp = $('Read inputs').first().json;
const contacts = $('Prepare transcription').first().json.contacts;
const transcript = $('Format transcript').first().json.transcript;
const speakers = contacts.filter(c => c.event_attendance_status === 'speaker')
  .map(c => `${c.firstname} ${c.lastname} (${c.jobtitle || ''}, ${c.company || ''})`);

const system = `You analyse a webinar transcript for post-event marketing.
The transcript lines look like "[mm:ss] Speaker N: text". Diarization labels are anonymous; map them to the real speakers listed.
Return ONLY valid JSON (inside string values never use the " character; use ' instead):
{
 "speaker_map": { "Speaker 0": "Full Name", ... },
 "event_summary": "2 sentences on what the session covered",
 "one_line_hook": "why someone who missed it should watch, max 25 words",
 "takeaways": [
   { "headline": "max 12 words", "detail": "1-2 sentences, faithful to what was said",
     "timestamp": "mm:ss", "speaker": "Full Name", "quote": "VERBATIM from the transcript, 10-35 words" }
 ],
 "best_quote_by_speaker": { "Full Name": { "quote": "VERBATIM, 10-35 words", "timestamp": "mm:ss" } }
}
Rules:
- Give exactly 5 takeaways, most valuable first, spread across the session.
- Quotes must be copied word for word from the transcript (you may cut at word boundaries; never paraphrase or fix grammar).
- Do not invent numbers, customers or claims that are not in the transcript.`;

return [{ json: {
  contacts, speakers,
  request_body: {
    model: 'deepseek-v4-pro', thinking: { type: 'disabled' }, temperature: 0.2, max_tokens: 4000,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: `Event: ${inp.event}\nSpeakers: ${speakers.join('; ')}\n\nTRANSCRIPT:\n${transcript}` },
    ],
  },
} }];

// M2 · Fact-guard the extracted quotes, compute the speaker performance snapshot,
// work out which personas/industries are in the audience, and build the copywriting request.

const inp = $('Read inputs').first().json;
const prev = $('Build insight prompt').first().json;
const contacts = prev.contacts;

// Tolerant JSON parse of a DeepSeek reply: strips ``` fences and repairs the two common breakages
// (raw line breaks and stray double quotes inside string values) with a small character scanner.
const parseAI = (resp, what) => {
  const c = resp && resp.choices && resp.choices[0];
  if (!c) throw new Error(`${what}: DeepSeek returned no answer: ${JSON.stringify(resp).slice(0, 300)}`);
  const t = String((c.message && c.message.content) || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  const raw = t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1);
  try { return JSON.parse(raw); } catch (e1) {}
  // common LLM slips: bare hashtags in arrays, trailing commas
  const raw2 = raw.replace(/([\[,]\s*)(#[A-Za-z0-9_]+)"?(?=\s*[,\]])/g, '$1"$2"')   // bare hashtags
    .replace(/,(\s*[}\]])/g, '$1');                                                    // trailing commas
  try { return JSON.parse(raw2); } catch (e2) {}
  let out = '', inStr = false;
  for (let i = 0; i < raw2.length; i++) {
    const ch = raw2[i];
    if (!inStr) { out += ch; if (ch === '"') inStr = true; continue; }
    if (ch === '\\') { out += ch + (raw2[i + 1] || ''); i++; continue; }
    if (ch === '\n') { out += '\\n'; continue; }
    if (ch === '\r' || ch === '\t') { out += ch === '\t' ? '\\t' : ''; continue; }
    if (ch === '"') {
      let j = i + 1; while (j < raw2.length && /\s/.test(raw2[j])) j++;
      if (j >= raw2.length || ',}]:'.includes(raw2[j])) { out += ch; inStr = false; } else out += '\\"';
      continue;
    }
    out += ch;
  }
  try { return JSON.parse(out); }
  catch (e) { throw new Error(`${what}: invalid JSON (finish_reason=${c.finish_reason}, ${t.length} chars). Starts: ${t.slice(0, 160)}`); }
};
const ins = parseAI($json, 'Insight extraction');

// ---------- fact guard: every quote must exist word-for-word in the transcript ----------
const norm = s => String(s || '').toLowerCase().replace(/[’']/g, '').replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const T = norm($('Format transcript').first().json.transcript);
const checked = (ins.takeaways || []).map(t => ({ ...t, quote_verified: !!t.quote && T.includes(norm(t.quote)) }));
const takeaways = checked.filter(t => t.quote_verified).slice(0, 3);
const rejected = checked.filter(t => !t.quote_verified).map(t => ({ headline: t.headline, quote: t.quote }));
if (takeaways.length < 3) throw new Error(`Only ${takeaways.length} takeaways passed the fact guard; refusing to write emails from unverified quotes`);
const bestQuotes = {};
for (const [name, q] of Object.entries(ins.best_quote_by_speaker || {}))
  if (q && T.includes(norm(q.quote))) bestQuotes[name] = q;

// ---------- performance snapshot (computed, never generated) ----------
const audience = contacts.filter(c => c.event_attendance_status !== 'speaker');
const attended = audience.filter(c => c.event_attendance_status === 'attended');
const pct = (a, b) => (b ? Math.round(100 * a / b) : 0);
const count = (arr, k) => arr.reduce((m, c) => (c[k] ? (m[c[k]] = (m[c[k]] || 0) + 1, m) : m), {});
const top = (m, n) => Object.entries(m).sort((a, b) => b[1] - a[1]).slice(0, n).map(([k]) => k);
const stats = {
  registrants: audience.length,
  attendees: attended.length,
  attendance_rate_pct: pct(attended.length, audience.length),
  avg_minutes: Math.round(attended.reduce((s, c) => s + Number(c.time_in_session_min || 0), 0) / (attended.length || 1)),
  stayed_30_plus_pct: pct(attended.filter(c => Number(c.time_in_session_min) >= 30).length, attended.length),
  questions: attended.reduce((s, c) => s + Number(c.questions_asked || 0), 0),
  director_plus_pct: pct(attended.filter(c => ['C-level', 'VP', 'Director'].includes(c.seniority)).length, attended.length),
  companies: new Set(audience.map(c => (c.company || '').toLowerCase())).size,
  countries: new Set(audience.map(c => c.country).filter(Boolean)).size,
  top_industries: top(count(audience, 'company_industry'), 3),
};

// ---------- personas in the audience ----------
const personaOf = c => {
  const fn = c.job_function, sen = c.seniority;
  if (['HRIS', 'IT'].includes(fn)) return 'hr_tech';
  if (['Talent Acquisition', 'L&D'].includes(fn)) return 'talent';
  if (['Finance', 'Operations'].includes(fn)) return 'finance_ops';
  if (['HR', 'Leadership', 'Total Rewards'].includes(fn)) return ['C-level', 'VP', 'Director'].includes(sen) ? 'hr_leader' : 'hr_practitioner';
  return 'other';
};
const industries = top(count(audience, 'company_industry'), 8);

const system = `You write post-webinar emails for an enterprise HR-tech company. Audience: HR leaders and HR tech owners.
Tone: warm, specific, concise, no hype, no emojis. Never use placeholders except {first_name} in subject lines.
Use ONLY the facts provided. Do not invent numbers, customers or features. No URLs (links are added later).
Describe the event only as what it was (a webinar conversation); never call it a launch, keynote or announcement unless the summary says so.
Any number you use must keep its exact meaning from the takeaways or stats (e.g. if a speaker says "four pillars", never write "3 pillars").
Avoid numbers in subject lines unless they come straight from the stats.
Return ONLY valid JSON (inside string values never use the " character; use ' instead):
{
 "takeaway_snippets": ["max 20 words, one per takeaway, same order: the so-what for an HR leader; must NOT repeat the headline"],
 "attendee": { "subjects": ["3 distinct subject lines, max 60 chars"], "preview": "max 90 chars",
               "intro": "thank them for attending, 1-2 sentences", "takeaways_lead": "short lead-in to the 3 takeaways",
               "recording_line": "1 sentence inviting them to rewatch or share the recording", "cta_line": "1 sentence leading to the CTA",
               "cta_text": "2-5 word button text", "closing": "1 sentence" },
 "no_show": { same keys as attendee; the intro is a friendly 'sorry we missed you' catch-up and the recording is the main CTA },
 "speaker": { "subjects": ["3 lines, max 60 chars"], "preview": "max 90 chars", "intro": "thank the speaker warmly and specifically, 2 sentences",
              "snapshot_lead": "1 sentence introducing the audience numbers", "closing": "1-2 sentences, e.g. offer to share the recording clips" },
 "persona_openers": { "hr_leader": "...", "hr_practitioner": "...", "hr_tech": "...", "talent": "...", "finance_ops": "...", "other": "..." },
 "industry_lines": { "<industry exactly as given>": "1 sentence tying the session to that industry" }
}
persona_openers: one sentence each, tying the session to what that persona cares about. Do not mention the person's name.`;

const user = JSON.stringify({
  event: inp.event, summary: ins.event_summary, hook: ins.one_line_hook,
  takeaways: takeaways.map(t => ({ headline: t.headline, detail: t.detail, quote: t.quote, speaker: t.speaker, timestamp: t.timestamp })),
  audience_stats_for_speaker_email: stats,
  industries_present: industries,
});

return [{ json: {
  contacts, takeaways, rejected, bestQuotes, stats, industries,
  persona_by_id: Object.fromEntries(contacts.map(c => [c.id, personaOf(c)])),
  speaker_map: ins.speaker_map || {}, summary: ins.event_summary, hook: ins.one_line_hook,
  request_body: {
    model: 'deepseek-v4-pro', thinking: { type: 'disabled' }, temperature: 0.6, max_tokens: 3000,
    response_format: { type: 'json_object' },
    messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  },
} }];

// M2 · Guardrail the generated copy, render the 3 segment emails, and personalise every contact
// (subject A/B/C variant, persona opener, industry line, UTM-tagged links) as HubSpot properties.

const inp = $('Read inputs').first().json;
const g = $('Fact guard + copy prompt').first().json;
// Tolerant JSON parse of a DeepSeek reply: strips ``` fences and repairs the two common breakages
// (raw line breaks and stray double quotes inside string values) with a small character scanner.
const parseAI = (resp, what) => {
  const c = resp && resp.choices && resp.choices[0];
  if (!c) throw new Error(`${what}: DeepSeek returned no answer: ${JSON.stringify(resp).slice(0, 300)}`);
  const t = String((c.message && c.message.content) || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  const raw = t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1);
  try { return JSON.parse(raw); } catch (e1) {}
  // common LLM slips: bare hashtags in arrays, trailing commas
  const raw2 = raw.replace(/([\[,]\s*)(#[A-Za-z0-9_]+)"?(?=\s*[,\]])/g, '$1"$2"')   // bare hashtags
    .replace(/,(\s*[}\]])/g, '$1');                                                    // trailing commas
  try { return JSON.parse(raw2); } catch (e2) {}
  let out = '', inStr = false;
  for (let i = 0; i < raw2.length; i++) {
    const ch = raw2[i];
    if (!inStr) { out += ch; if (ch === '"') inStr = true; continue; }
    if (ch === '\\') { out += ch + (raw2[i + 1] || ''); i++; continue; }
    if (ch === '\n') { out += '\\n'; continue; }
    if (ch === '\r' || ch === '\t') { out += ch === '\t' ? '\\t' : ''; continue; }
    if (ch === '"') {
      let j = i + 1; while (j < raw2.length && /\s/.test(raw2[j])) j++;
      if (j >= raw2.length || ',}]:'.includes(raw2[j])) { out += ch; inStr = false; } else out += '\\"';
      continue;
    }
    out += ch;
  }
  try { return JSON.parse(out); }
  catch (e) { throw new Error(`${what}: invalid JSON (finish_reason=${c.finish_reason}, ${t.length} chars). Starts: ${t.slice(0, 160)}`); }
};
const copy = parseAI($json, 'Copy generation');

// ---------- guardrails ----------
const issues = [];
const allowedNumbers = new Set([...JSON.stringify(g.stats).matchAll(/\d+/g)].map(m => m[0])
  .concat([...$('Format transcript').first().json.transcript.matchAll(/\d+/g)].map(m => m[0])).concat(['1', '2', '3']));
const checkText = (where, s) => {
  if (!s || typeof s !== 'string') { issues.push(`${where}: missing`); return; }
  if (/\{\{|\}\}|https?:\/\//.test(s)) issues.push(`${where}: contains a token or URL`);
  for (const n of s.match(/\d+/g) || []) if (!allowedNumbers.has(n)) issues.push(`${where}: number "${n}" is not in the data`);
};
for (const seg of ['attendee', 'no_show', 'speaker']) {
  const c = copy[seg] || {};
  if (!Array.isArray(c.subjects) || c.subjects.length < 3) issues.push(`${seg}: needs 3 subject lines`);
  (c.subjects || []).forEach((s, i) => { if (s.length > 70) issues.push(`${seg} subject ${i + 1} longer than 70 chars`); });
  for (const [k, v] of Object.entries(c)) if (k !== 'subjects') checkText(`${seg}.${k}`, v);
}
(copy.takeaway_snippets || []).forEach((s, i) => checkText(`snippet ${i + 1}`, s));
const blocking = issues.filter(i => /missing|token or URL|needs 3/.test(i));
if (blocking.length) throw new Error('Copy failed guardrails: ' + blocking.join('; '));

// ---------- helpers ----------
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const utm = (url, content) => {
  if (!url) return '';
  const [base, hashPart] = url.split('#');
  const q = `utm_source=hubspot&utm_medium=email&utm_campaign=${encodeURIComponent(inp.utm_campaign)}&utm_content=${encodeURIComponent(content)}`;
  return base + (base.includes('?') ? '&' : '?') + q + (hashPart ? '#' + hashPart : '');
};
const hash = s => [...String(s)].reduce((h, ch) => (h * 31 + ch.charCodeAt(0)) >>> 0, 7);
const VARIANTS = ['A', 'B', 'C'];

const takeawaysHtml = g.takeaways.map((t, i) => `<li style="margin-bottom:12px"><strong>${esc(copy.takeaway_snippets?.[i] || t.headline)}</strong><br>
<em style="color:#555">&ldquo;${esc(t.quote)}&rdquo; &mdash; ${esc(t.speaker)}, ${esc(t.timestamp)}</em></li>`).join('');
const button = (href, text) => `<p style="margin:20px 0"><a href="${href}" style="background:#1f5eff;color:#ffffff;padding:11px 18px;border-radius:6px;text-decoration:none;font-weight:600;display:inline-block">${esc(text)}</a></p>`;
const sign = `<p>${esc(inp.from_name)}</p>`;

const html = {
  attendee: `<p>Hi {{ personalization_token('contact.firstname', 'there') }},</p><p>${esc(copy.attendee.intro)}</p><p>{{ contact.pe_opening_line }}</p>
<p><strong>${esc(copy.attendee.takeaways_lead)}</strong></p><ol>${takeawaysHtml}</ol>
<p>{{ contact.pe_industry_line }}</p><p>${esc(copy.attendee.recording_line)}</p>
${button('{{ contact.pe_recording_url }}', 'Watch the recording')}
<p>${esc(copy.attendee.cta_line)} <a href="{{ contact.pe_cta_url }}">${esc(copy.attendee.cta_text)}</a></p>
<p>${esc(copy.attendee.closing)}</p>${sign}`,
  no_show: `<p>Hi {{ personalization_token('contact.firstname', 'there') }},</p><p>${esc(copy.no_show.intro)}</p><p>{{ contact.pe_opening_line }}</p>
${button('{{ contact.pe_recording_url }}', 'Watch the full recording')}
<p><strong>${esc(copy.no_show.takeaways_lead)}</strong></p><ol>${takeawaysHtml}</ol>
<p>{{ contact.pe_industry_line }}</p><p>${esc(copy.no_show.cta_line)} <a href="{{ contact.pe_cta_url }}">${esc(copy.no_show.cta_text)}</a></p>
<p>${esc(copy.no_show.closing)}</p>${sign}`,
  speaker: `<p>Hi {{ personalization_token('contact.firstname', 'there') }},</p><p>${esc(copy.speaker.intro)}</p>
<p><strong>${esc(copy.speaker.snapshot_lead)}</strong></p>
<table cellpadding="6" style="border-collapse:collapse;font-size:14px">
<tr><td>Registered</td><td><strong>${g.stats.registrants}</strong> people from ${g.stats.companies} companies in ${g.stats.countries} countries</td></tr>
<tr><td>Attended live</td><td><strong>${g.stats.attendees}</strong> (${g.stats.attendance_rate_pct}% of registrants)</td></tr>
<tr><td>Avg. time watched</td><td><strong>${g.stats.avg_minutes} min</strong>; ${g.stats.stayed_30_plus_pct}% stayed 30+ min</td></tr>
<tr><td>Audience questions</td><td><strong>${g.stats.questions}</strong></td></tr>
<tr><td>Director level or above</td><td><strong>${g.stats.director_plus_pct}%</strong> of attendees</td></tr>
<tr><td>Top industries</td><td>${esc(g.stats.top_industries.join(', '))}</td></tr></table>
<p><strong>Your most-quoted moment:</strong><br><em>{{ contact.pe_speaker_quote }}</em></p>
${button('{{ contact.pe_recording_url }}', 'See the recording')}
<p>${esc(copy.speaker.closing)}</p>${sign}`,
};

// ---------- per-contact personalisation ----------
const SEG = { attended: 'attendee', no_show: 'no_show', speaker: 'speaker' };
const members = { attendee: [], no_show: [], speaker: [] };
const nowIso = new Date().toISOString();
const inputs = g.contacts.map(c => {
  const seg = SEG[c.event_attendance_status] || 'no_show';
  const v = hash(c.id) % 3, variant = VARIANTS[v];
  const persona = g.persona_by_id[c.id] || 'other';
  members[seg].push(c.id);
  const name = `${c.firstname || ''} ${c.lastname || ''}`.trim();
  const q = g.bestQuotes[name];
  const props = {
    pe_subject: (copy[seg].subjects[v] || copy[seg].subjects[0]).replace(/\{first_name\}/g, c.firstname || 'there'),
    pe_opening_line: seg === 'speaker' ? '' : (copy.persona_openers?.[persona] || ''),
    pe_industry_line: copy.industry_lines?.[c.company_industry] || '',
    pe_recording_url: utm(inp.recording_url, `${seg}_${variant}`),
    pe_cta_url: utm(inp.cta_url || inp.recording_url, `${seg}_${variant}_cta`),
    pe_speaker_snapshot: seg === 'speaker' ? `${g.stats.attendees} attended live (${g.stats.attendance_rate_pct}%), avg ${g.stats.avg_minutes} min, ${g.stats.questions} questions` : '',
    pe_speaker_quote: seg === 'speaker' && q ? `"${q.quote}" (${q.timestamp})` : '',
    postevent_email_variant: `${seg}_${variant}_${persona}`,
    utm_campaign_postevent: inp.utm_campaign,
    pe_sent_at: nowIso,
  };
  return { id: c.id, properties: props };
});

const LABEL = { attendee: 'Attendees: thank-you', no_show: 'No-shows: catch-up', speaker: 'Speakers: thank-you' };
const segments = Object.keys(html).map(seg => ({
  segment: seg, label: LABEL[seg], member_ids: members[seg],
  list: { name: `${inp.event.slice(0, 60)} · ${LABEL[seg]} · ${inp.runId}`, objectTypeId: '0-1', processingType: 'MANUAL' },
  email: {
    name: `${inp.event.slice(0, 60)} · ${LABEL[seg]} · ${inp.runId}`,
    subject: '{{ contact.pe_subject }}',
    from: { fromName: inp.from_name, replyTo: inp.reply_to || undefined },
    content: { templatePath: '@hubspot/email/dnd/Plain_email.html',
      widgets: { primary_rich_text_module: { id: 'primary_rich_text_module', name: 'primary_rich_text_module', type: 'module',
        module_id: 1155639, body: { html: html[seg], module_id: 1155639 } } } },
  },
  subjects: copy[seg].subjects, preview: copy[seg].preview,
}));

return [{ json: { batch: { inputs }, segments, issues, copy, takeaways: g.takeaways, rejected: g.rejected, stats: g.stats } }];

// M2 · Summary shown on the form's result page.

const p = $('Personalise').first().json;
const inp = $('Read inputs').first().json;
const segs = $('Split segments').all().map(i => i.json);
const emails = $('Create email').all().map(i => i.json || {});
const lines = segs.map((s, i) =>
